// client/src/features/dashboard/attendee/JoinSession.jsx
import React, { useEffect, useRef, useState } from 'react';
import { useLocation, Link }            from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const JoinSession = () => {
  const { search }  = useLocation();
  const link        = new URLSearchParams(search).get('link');
  const videoRef    = useRef(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!link) return;

    // If it's an https URL, we embed via iframe—no camera capture needed:
    if (link.startsWith('http')) return;

    // Otherwise treat it as a "room name" and open your camera
    let stream;
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(s => {
        stream = s;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      })
      .catch(err => {
        console.error('Media error:', err);
        setError('Unable to access camera/microphone.');
      });

    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
    };
  }, [link]);

  return (
    <div className="container">
      <div className="card" style={{ minHeight: '650px' }}>
        <h2>Live Session {link && !link.startsWith('http') && <>• <em>{link}</em></>}</h2>

        {!link && (
          <p style={{ color: 'red' }}>No session link provided.</p>
        )}

        {/* 1) External iframe embed */}
        {link && link.startsWith('http') && (
          <iframe
            src={link}
            title="Live Session"
            width="100%"
            height="600"
            style={{ border: 'none', borderRadius: '8px' }}
          />
        )}

        {/* 2) Local camera preview */}
        {link && !link.startsWith('http') && (
          <>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              style={{
                width:  '100%',
                height: '600px',
                background: '#000',
                borderRadius: '8px'
              }}
            />
          </>
        )}

        <Link to="/attendee/dashboard">
          <button className="btn" style={{ marginTop: '1rem' }}>
            Back to Dashboard
          </button>
        </Link>
      </div>
    </div>
  );
};

export default JoinSession;
